B.Jz=new A.aO(B.cc,["1\ucc28 \ud06c\ub864\ub9c1 \u2014 \uad00\uc2ec\uc0ac \uc804\ubc18","\uc561\ud2f0\ube0c \uc2dc\ub2c8\uc5b4\ub294 \uc5b4\ub5a4 \uac83\uc5d0 \uad00\uc2ec\uc774 \uc788\uc744\uae4c\ub77c\ub294 \uc5f4\ub9b0 \uc9c8\ubb38\uc73c\ub85c \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4. \uc2dc\ub2c8\uc5b4 \ub77c\uc774\ud504\uc2a4\ud0c0\uc77c \uce74\ud398 3\uacf3\uc5d0\uc11c 5,197\uac74\uc744 \ubaa8\uc544 \uc804\ucc98\ub9ac \ud6c4 4,889\uac74\uc744 \ud655\ubcf4\ud588\uc2b5\ub2c8\ub2e4."],t.l)
B.Jx=new A.aO(B.cc,["\ud575\uc2ec \ud0a4\uc6cc\ub4dc \ub3c4\ucd9c","\ub178\ud6c4\uc18c\ub4dd, \uac74\uac15\uc5ec\uac00, \uac00\uc871, \uc5ec\ud589\uc5ec\uac00 \ub4f1\uc73c\ub85c \uc8fc\uc81c\uac00 \ub098\ub258\uc5c8\ub294\ub370, \uadf8\uc911 \uc5ec\ud589\xb7\uc5ec\uac00\uac00 879\uac74\uc73c\ub85c \uac00\uc7a5 \ub450\ub4dc\ub7ec\uc84c\uc2b5\ub2c8\ub2e4. \ub610\ud55c, \uc561\ud2f0\ube0c \uc2dc\ub2c8\uc5b4\uc758 \uc18c\ube44\uc9c0\ucd9c \uc911 \uc5ec\uac00\ud65c\ub3d9\uc758 \uc9c0\ucd9c\uc774 40% \uc774\uc0c1\uc774\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc5ec\ud589\uc744 \uc561\ud2f0\ube0c \uc2dc\ub2c8\uc5b4\uc758 \ud575\uc2ec \ud0a4\uc6cc\ub4dc\ub85c \uc120\uc815\ud588\uc2b5\ub2c8\ub2e4."],t.l)
B.Jy=new A.aO(B.cc,["2\ucc28 \ud06c\ub864\ub9c1 \u2014 \uc5ec\ud589\uc73c\ub85c \uc9d1\uc911","\uc561\ud2f0\ube0c \uc2dc\ub2c8\uc5b4\ub294 \uc5ec\ud589\uc5d0\uc11c \uc5b4\ub5a4 \uc990\uac70\uc6c0\uacfc \uace0\ud1b5\uc744 \uacaa\uace0 \uc788\ub294\uc9c0 \ud30c\uc545\ud558\uae30 \uc704\ud574 \uc5ec\ud589 \uad00\ub828 \uce74\ud398\xb7\ube14\ub85c\uadf8\uc5d0\uc11c 41,411\uac74\uc758 \ub370\uc774\ud130\ub97c \ucd94\uac00\ub85c \uc218\uc9d1\ud588\uc2b5\ub2c8\ub2e4."],t.l)
B.Ju=new A.aO(B.cc,["\ubd84\ub958\uae30\ub85c \uc815\uc81c","SBERT+RandomForest\ub85c \uc5ec\ud589 \uad00\ub828 \ub0b4\uc6a9 \uc5ec\ubd80\ub97c \ud310\ubcc4\ud558\ub294 \ubd84\ub958\uae30\ub97c \ub9cc\ub4e4\uc5b4(F1-Score 0.95) \ubb34\uad00\ud55c \ub370\uc774\ud130\ub97c \uac78\ub7ec\ub0c8\uc2b5\ub2c8\ub2e4. \ucd5c\uc885 16,027\uac74\uc774 \ub0a8\uc558\uc2b5\ub2c8\ub2e4."],t.l)
